// The copy lint: the deterministic check on every public word around a piece.
//
// Krish, 2026-10-28: "don't add stupid eyebrow text and asterisks and
// "generated by AI" and "Krish's take" verbal diahorrea like you tend to. This
// needs to feel like a world class media channel". With his 26 October ruling
// that no illustration-generation boilerplate goes on public artwork, captions
// or descriptions (docs/CAROUSEL-STANDARD.md).
//
// The patterns live once, in config/copy-lint.json. scripts/post-pack/copy_lint.py
// reads the same file, so CI (scripts/check-public-copy.ts) and every session
// that runs it read the same patterns, and tests/control-plane/copy-lint.test.ts
// holds the two to the same answers.
// Each pattern names the surfaces it covers. Only the name rule (no_name:
// Krish, 2026-10-28, "no content refers to Krish, ever") covers the article
// body; no other pattern reads the body's markdown source, where emphasis and
// headings are the markdown itself.
//
// Pure and network-free: it runs before any paid call.

import lint from '../../../config/copy-lint.json' with { type: 'json' }

export const COPY_SURFACES = ['channel_copy', 'carousel_text', 'video_onscreen', 'titles', 'article_metadata', 'article_body'] as const
export type CopySurface = (typeof COPY_SURFACES)[number]

export interface CopyLintHit {
  id: string
  match: string
  index: number
}

interface PatternSpec {
  id: string
  regex: string
  flags: string
  reason: string
  applies_to: string[]
}

export const COPY_LINT_VERSION: string = lint.version

const PATTERNS = (lint.patterns as PatternSpec[]).map((p) => {
  // Only the flags Python's re reads the same way (i, m), so both sides agree.
  if (!/^[im]*$/.test(p.flags)) throw new Error(`copy-lint pattern ${p.id}: flags must be i and m only`)
  return { id: p.id, reason: p.reason, appliesTo: p.applies_to, regex: new RegExp(p.regex, `${p.flags}g`) }
})

/** Line ends as \n and every odd space as a plain one, as the Python lint reads them. */
export function normaliseCopy(text: string): string {
  // U+2028 and U+2029 end a line for JavaScript's ^, $ and \s but not for
  // Python's ASCII rules, and pasted text can end a line with U+0085, so both
  // readers turn all three into \n first.
  return text
    .replace(/\r\n?/g, '\n')
    .replace(/[\u2028\u2029\u0085]/g, '\n')
    .replace(/[\u00a0\u1680\u2000-\u200a\u202f\u205f\u3000\ufeff]/g, ' ')
}

/** Every hit in one piece of public copy, in order of where it starts. */
export function copyLint(text: string, appliesTo: string): CopyLintHit[] {
  if (!(COPY_SURFACES as readonly string[]).includes(appliesTo)) {
    throw new Error(`appliesTo must be one of ${COPY_SURFACES.join(', ')}, not ${appliesTo}`)
  }
  const copy = normaliseCopy(text ?? '')
  const hits: CopyLintHit[] = []
  for (const p of PATTERNS) {
    if (!p.appliesTo.includes(appliesTo)) continue
    for (const m of copy.matchAll(p.regex)) {
      if (m[0] === '') continue
      hits.push({ id: p.id, match: m[0], index: m.index ?? 0 })
    }
  }
  return hits.sort((a, b) => a.index - b.index || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
}

/** Why a pattern refuses copy, in the words of config/copy-lint.json. */
export function copyLintReason(id: string): string {
  return PATTERNS.find((p) => p.id === id)?.reason ?? ''
}

export interface CopyField {
  where: string
  text: string
  appliesTo: CopySurface
}

type Json = Record<string, unknown>
const isObj = (v: unknown): v is Json => typeof v === 'object' && v !== null && !Array.isArray(v)
const list = (v: unknown): unknown[] => (Array.isArray(v) ? v : [])
const str = (v: unknown): string | null => (typeof v === 'string' ? v : null)

/**
 * Every public word in one of the engine's JSON shapes, each as the surface it
 * is. The same reading as copy_lint.py's fields():
 *   board materials     sections[].copy[] (a label with "title" in it is a title)
 *   carousel cards      cards[].kicker, cards[].lines[].text
 *   cover facts         headline and deck (article metadata), video_title,
 *                       comment_question and the cover and thumbnail words
 *   creative direction  cuts.<cut>.beats[].on_screen_text
 *   publish manager     title (title), subtitle and every picture's alt text
 *                       (article metadata)
 */
export function copyFields(data: unknown): CopyField[] {
  const out: CopyField[] = []
  if (!isObj(data)) return out
  list(data.sections).forEach((section, si) => {
    list(isObj(section) ? section.copy : null).forEach((item, ci) => {
      if (!isObj(item)) return
      const text = str(item.text)
      if (text === null) return
      const label = str(item.label) ?? ''
      out.push({ where: `sections[${si}].copy[${ci}] (${label})`, text, appliesTo: /\btitle\b/i.test(label) ? 'titles' : 'channel_copy' })
    })
  })
  list(data.cards).forEach((card, ki) => {
    if (!isObj(card)) return
    const kicker = str(card.kicker)
    if (kicker !== null) out.push({ where: `cards[${ki}].kicker`, text: kicker, appliesTo: 'carousel_text' })
    list(card.lines).forEach((line, li) => {
      const text = isObj(line) ? str(line.text) : null
      if (text !== null) out.push({ where: `cards[${ki}].lines[${li}]`, text, appliesTo: 'carousel_text' })
    })
  })
  const facts = 'subchannel' in data || 'cover' in data || 'thumbs' in data
  for (const [key, surface] of [['headline', 'article_metadata'], ['deck', 'article_metadata'], ['video_title', 'titles'], ['comment_question', 'video_onscreen']] as const) {
    const text = str(data[key])
    if (text !== null && facts) out.push({ where: key, text, appliesTo: surface })
  }
  for (const panel of ['cover', 'thumbs'] as const) {
    const block = data[panel]
    if (!isObj(block)) continue
    list(block.headline).forEach((words, hi) => {
      const text = str(words)
      if (text !== null) out.push({ where: `${panel}.headline[${hi}]`, text, appliesTo: 'video_onscreen' })
    })
    for (const group of ['rows', 'strip'] as const) {
      list(block[group]).forEach((row, ri) => {
        if (!isObj(row)) return
        for (const key of ['name', 'tag'] as const) {
          const text = str(row[key])
          if (text !== null) out.push({ where: `${panel}.${group}[${ri}].${key}`, text, appliesTo: 'video_onscreen' })
        }
      })
    }
  }
  if (isObj(data.cuts)) {
    for (const [cut, spec] of Object.entries(data.cuts)) {
      list(isObj(spec) ? spec.beats : null).forEach((beat, bi) => {
        const text = isObj(beat) ? str(beat.on_screen_text) : null
        if (text !== null && text.trim()) out.push({ where: `cuts.${cut}.beats[${bi}].on_screen_text`, text, appliesTo: 'video_onscreen' })
      })
    }
  }
  // publish_manager.py's manager.json: a title, the body's path and the pictures.
  const title = str(data.title)
  if (title !== null && str(data.body) !== null && Array.isArray(data.images)) {
    out.push({ where: 'title', text: title, appliesTo: 'titles' })
    const subtitle = str(data.subtitle)
    if (subtitle !== null) out.push({ where: 'subtitle', text: subtitle, appliesTo: 'article_metadata' })
    data.images.forEach((image, ii) => {
      const alt = isObj(image) ? str(image.alt) : null
      if (alt !== null) out.push({ where: `images[${ii}].alt`, text: alt, appliesTo: 'article_metadata' })
    })
  }
  return out
}
